#!/usr/bin/env bash
# Build the probe app (tests/e2e/app) with Flutter's own Linux (GTK)
# embedder, for running the scenarios against it: `run.py --reference`.
#
# The Linux runner is generated by `flutter create` into app/build/reference,
# which is not kept in git, and changed in one way: the window gets no
# title bar, so that the app's picture fills the window as it does in Flust.
set -euo pipefail

cd "$(dirname "$(readlink -f "$0")")/app"

reference=build/reference
mkdir -p "$reference"
rm -rf "$reference/lib"
cp -r lib pubspec.yaml "$reference/"
cd "$reference"

runner=linux/runner/my_application.cc
if [ ! -f "$runner" ]; then
    flutter create --platforms=linux --project-name flust_e2e_probe .
    sed -i \
        -e 's/gboolean use_header_bar = TRUE;/gboolean use_header_bar = FALSE;/' \
        -e 's/^\( *\)gtk_window_set_default_size(/\1gtk_window_set_decorated(window, FALSE);\n&/' \
        "$runner"
    grep -q 'gtk_window_set_decorated(window, FALSE);' "$runner" || {
        echo "could not patch $runner: the runner template has changed" >&2
        exit 1
    }
fi

flutter build linux --debug

echo "built: $(pwd)/build/linux/x64/debug/bundle/flust_e2e_probe"
